def est(d):
    g=d.groupby(['genre','late']).r.mean().unstack()
    return (g[True]-g[False]).mean()
def boot(d,B=2000):
    rng=np.random.default_rng(0);out=[]
    gs=[x for _,x in d.groupby(['genre','late'])]
    for _ in range(B):
        out.append(est(pd.concat([x.sample(len(x),replace=True,random_state=rng.integers(1e9)) for x in gs])))
    return np.percentile(out,[2.5,97.5])
